// ============================================================
// Portero de la lista de espera: valida y frena el abuso ANTES
// de tocar la planilla. Este endpoint es publico, asi que todo
// lo que entra se trata como hostil hasta probar lo contrario.
// ============================================================

const TOPE_DIARIO = 500;   // altas por dia en total (organico deja de sobra margen)
const ORIGENES = [          // de donde acepta pedidos
  'https://obolfinance.com.ar',
  'https://obolfinance.github.io'
];

const entrada = $('Recibe el formulario').item.json;
// El widget manda el JSON como text/plain para evitar el preflight CORS,
// asi que el body puede llegar como objeto o como string. Contemplamos los dos casos.
const crudo = entrada.body ?? entrada;
let d;
try {
  d = typeof crudo === 'string' ? JSON.parse(crudo) : crudo;
} catch (e) {
  d = {};
}

function rechazar(motivo) {
  return [{ json: { ok: false, motivo } }];
}

// 0. Turnstile: Cloudflare ya confirmo (o no) que esto lo mando un humano.
const turnstileOk = $('Verifica Turnstile').item.json.success === true;
if (!turnstileOk) return rechazar('bot');

// 1. Origen. No es seguridad real (se falsifica facil), pero filtra el ruido.
const headers = entrada.headers || {};
const origen = headers.origin || headers.referer || '';
if (ORIGENES.length && !ORIGENES.some(o => origen.startsWith(o))) {
  return rechazar('origen');
}

// 2. Tope diario global. Es el freno que evita que te llenen la planilla de spam.
const estado = $getWorkflowStaticData('global');
const hoy = new Date().toISOString().slice(0, 10);
if (estado.dia !== hoy) { estado.dia = hoy; estado.cuenta = 0; }
if (estado.cuenta >= TOPE_DIARIO) return rechazar('limite');

const email = String(d.email || '').trim().toLowerCase();
const valido = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email);

// Dominios descartables mas comunes
const descartables = ['mailinator.com', 'tempmail.com', 'guerrillamail.com', '10minutemail.com', 'yopmail.com'];
const dominio = email.split('@')[1] || '';
const esDescartable = descartables.includes(dominio);

const puntaje = Number.isFinite(Number(d.puntaje)) ? Number(d.puntaje) : null;

// Segmento: sirve para escribirle distinto a cada grupo cuando lances
let segmento = 'sin_dato';
if (puntaje !== null) {
  if (puntaje <= 2) segmento = 'arranca_de_cero';
  else if (puntaje <= 4) segmento = 'sabe_algo';
  else segmento = 'ya_la_tiene_clara';
}

const ok = valido && !esDescartable;
if (ok) estado.cuenta = (estado.cuenta || 0) + 1;

return [{
  json: {
    ok,
    motivo: !valido ? 'email_invalido' : (esDescartable ? 'email_descartable' : ''),
    email,
    nombre: String(d.nombre || '').trim(),
    puntaje,
    total: d.total ?? null,
    segmento,
    origen: d.origen || 'desconocido',
    pagina: d.pagina || '',
    referrer: d.referrer || 'directo',
    fecha: d.fecha || new Date().toISOString()
  }
}];
